/**
 * Pipeline board with a confirmed write. Stage counts are one `knowledge_aggregate` grouped by the
 * stage field, so any entity type with a stage column works (no schema `pipeline` declaration is
 * needed, unlike `knowledge_pipeline_summary`, which returns no stages without one). Pick a stage
 * to list its records; "Advance" asks for
 * confirmation, then runs the one automation tools.json grants, with the one action it allows.
 * The automation's handler (automations/handlers/ADVANCE_AUTOMATION/) checks the viewer's role and
 * reports `rowsAffected`, so the run settles as applied, conflict or accepted.
 */
import { createRoot } from 'react-dom/client';
import { useState } from 'react';
import { Pipeline, SurfaceApp, toast, useConfirm, useMutation, useQuery } from '@cynap/surface-sdk';

import './styles.css';

/** The org's entity type, its stage field, and the stage order. Replace all three; the handler holds the same order. */
const ENTITY_TYPE = 'REPLACE_WITH_ENTITY_TYPE';
const STAGE_FIELD = 'stage';
const STAGES = ['REPLACE_WITH_FIRST_STAGE', 'REPLACE_WITH_NEXT_STAGE'];
/** Must match tools.json `automationIds` and `triggerActions`. */
const ADVANCE_AUTOMATION = 'pipeline-writes-advance';
const ADVANCE_ACTION = 'advance';

type Row = Record<string, unknown>;
type Stage = { name: string; count: number };

const isRecord = (value: unknown): value is Row => typeof value === 'object' && value !== null && !Array.isArray(value);

/** `knowledge_aggregate` grouped by the stage field returns `{group, count}` rows; every stage gets a column. */
function readStages(payload: unknown): Stage[] | null {
  if (!isRecord(payload) || !Array.isArray(payload.rows)) return null;
  const counts = new Map<string, number>();
  for (const row of payload.rows.filter(isRecord)) counts.set(String(row.group ?? ''), Number(row.count) || 0);
  return STAGES.map((name) => ({ name, count: counts.get(name) ?? 0 }));
}

function readRows(payload: unknown): Row[] | null {
  return isRecord(payload) && Array.isArray(payload.rows) ? payload.rows.filter(isRecord) : null;
}

function Board() {
  const [active, setActive] = useState<string | null>(null);
  const confirm = useConfirm();
  const stages = useQuery(
    'knowledge_query_data',
    { tool: 'knowledge_aggregate', params: { entity_type: ENTITY_TYPE, group_by: STAGE_FIELD } },
    { parse: readStages }
  );
  const records = useQuery(
    'knowledge_query_data',
    { tool: 'knowledge_advanced_query', params: { entity_type: ENTITY_TYPE, filter: { [STAGE_FIELD]: active ?? '' }, limit: 50 } },
    { parse: readRows, enabled: active !== null, keepPrevious: true }
  );
  const advance = useMutation('automation_run_manual', { invalidates: ['knowledge_'] });

  async function onAdvance(record: Row) {
    const name = String(record.name ?? record.id);
    const ok = await confirm({ title: `Advance ${name}?`, body: 'This moves the record to the next stage.', confirmLabel: 'Advance' });
    if (!ok) return;
    const verdict = await advance.mutate({
      automation_id: ADVANCE_AUTOMATION,
      trigger_data: { action: ADVANCE_ACTION, record_id: String(record.id), from_stage: active ?? '' },
    });
    if (verdict === 'applied') toast(`${name} advanced.`, { tone: 'success' });
    else if (verdict === 'conflict') toast(`${name} changed since you loaded it. Reload and try again.`, { tone: 'error' });
    else if (verdict === 'accepted') toast('Sent; the outcome is not confirmed yet.', { tone: 'info' });
    else toast('The change did not go through.', { tone: 'error' });
  }

  return (
    <main className="tpl-page">
      <Pipeline
        stages={(stages.data ?? []).map((stage) => ({ ...stage, color: 'var(--color-ring-primary)' }))}
        isLoading={stages.state === 'loading'}
        activeStage={active ?? undefined}
        onStageClick={(stage) => setActive(stage.name)}
      />
      {active !== null && (
        <ul className="tpl-list" aria-label={`Records in ${active}`}>
          {(records.data ?? []).map((record) => (
            <li key={String(record.id)} className="tpl-row">
              <span>{String(record.name ?? record.id)}</span>
              <button type="button" className="tpl-button" disabled={advance.state === 'pending'} onClick={() => void onAdvance(record)}>
                Advance
              </button>
            </li>
          ))}
        </ul>
      )}
    </main>
  );
}

const root = document.getElementById('root');
if (root) {
  createRoot(root).render(
    <SurfaceApp info={{ name: 'pipeline-writes', version: '1.0.0' }}>
      <Board />
    </SurfaceApp>
  );
}

